def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    strong_prev_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    strong_prev_bids.append(float(bid))

    if not alive_opps:
        return max(0.0, min(budget, 20.0))

    req_players = 1
    for opp in alive_opps:
        req = opp.get('water_requirement', WATER_REQ)
        if req and supply >= req:
            req_players += 1

    scarcity = supply / float(WATER_REQ * req_players)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    active_high = max(strong_prev_bids) if strong_prev_bids else highest_prev
    low_prev = min(prev_bids) if prev_bids else 0.0

    critical = hp <= 3 or no_water >= 2
    pressured = hp <= 5 or no_water >= 1

    if critical:
        target = max(150.0, active_high + 2.0)
        if supply >= 22:
            target -= 10.0
        return max(0.0, min(budget, target))

    if scarcity >= 1.2:
        target = 18.0
        if pressured:
            target = 45.0
        if highest_prev < 100:
            target = max(target, low_prev + 1.0 if prev_bids else target)
        return max(0.0, min(budget, target))

    if scarcity >= 0.9:
        target = 55.0
        if pressured:
            target = 95.0
        if prev_bids:
            target = max(target, min(active_high - 35.0, 110.0))
        return max(0.0, min(budget, target))

    target = 85.0
    if prev_bids:
        target = max(target, min(active_high - 8.0, 155.0))
    if pressured:
        target = max(target, min(active_high + 1.5, 165.0))
    if supply <= 16:
        target += 8.0
    if day >= 8 and hp >= 6 and no_water == 0:
        target -= 12.0

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        cap = DAILY_SALARY * 0.4
        return max(0.0, min(budget, cap))

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    # Determine pressure from opponent behavior
    # Cindy's pattern suggests some agents bid aggressively; Alex/Eric/David show punishment when budgets run out.
    pressure_level = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.7:  # ~153+
        pressure_level = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        pressure_level = 0.7
    else:
        pressure_level = 0.4

    # Base target bid depends on hp and no_water_days
    if hp <= 2.0 or no_water_days >= 2:
        # Need to secure water now
        base = DAILY_SALARY * (0.85 + 0.1 * pressure_level)
    elif hp <= 4.0:
        base = DAILY_SALARY * (0.65 + 0.15 * pressure_level)
    else:
        base = DAILY_SALARY * (0.50 + 0.12 * pressure_level)

    # Scale with supply: lower supply -> bid more to compete
    if supply <= float(WATER_REQ):
        supply_factor = 1.15
    elif supply <= 18.0:
        supply_factor = 1.05
    else:
        supply_factor = 0.95

    target = base * supply_factor

    # If yesterday saw very high bids, slightly undercut to avoid budget death
    # but still stay near the competitive band.
    if highest_prev_bid > 0:
        # Competitive band midpoint: either chase avg or just below highest.
        band = max(avg_prev_bid, highest_prev_bid * 0.78)
        target = max(target, band * 0.95)

    # Final caps to avoid overspending
    # With water requirement 9 and supply range 15-25, winning often doesn't require extreme bids.
    max_cap = DAILY_SALARY * (1.25 if pressure_level >= 0.7 else 1.05)
    bid = min(budget, max_cap, target)

    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev > DAILY_SALARY:
            return min(my_status['budget'], DAILY_SALARY * 0.7)
        return min(my_status['budget'], max_prev + 5.0)

